// Normalize the trigger output into a flat shape the rest of the workflow can rely on.
// The Gmail Trigger (Simplify OFF) returns the email already parsed: subject, from, text, html.
// We also support the raw Gmail API shape (payload.headers + base64url body parts) as a fallback.
// IMPORTANT: snippet is only a ~100-200 char preview, so it is used only as a last resort.
const msg = $input.item.json;

function b64urlDecode(data) {
  try {
    return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
  } catch {
    return '';
  }
}

function findPart(part, mimeType) {
  if (!part) return null;
  if (part.mimeType === mimeType && part.body?.data) return b64urlDecode(part.body.data);
  if (part.parts) {
    for (const p of part.parts) {
      const found = findPart(p, mimeType);
      if (found) return found;
    }
  }
  return null;
}

const stripHtml = (h) => String(h).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

// --- Subject / sender ---
const rawHeaders = Array.isArray(msg.payload?.headers) ? msg.payload.headers : [];
const rawGet = (name) => rawHeaders.find(h => h.name.toLowerCase() === name.toLowerCase())?.value || '';
const fromField = msg.from;
const from = (typeof fromField === 'string' ? fromField : fromField?.text) || rawGet('From') || msg.From || '';
const subject = (typeof msg.subject === 'string' ? msg.subject : '') || rawGet('Subject') || msg.Subject || '';

// --- Body ---
let body = '';
if (typeof msg.text === 'string' && msg.text.trim()) {
  body = msg.text;
} else if (typeof msg.html === 'string' && msg.html.trim()) {
  body = stripHtml(msg.html);
} else if (msg.payload) {
  const plain = findPart(msg.payload, 'text/plain');
  const html = plain ? null : findPart(msg.payload, 'text/html');
  body = plain || (html ? stripHtml(html) : '') || (msg.payload.body?.data ? b64urlDecode(msg.payload.body.data) : '');
}
body = (body || msg.snippet || '').trim().slice(0, 6000);

// --- Address to reply to (Reply-To wins over From) ---
const addrRe = /[^\s<>,;"']+@[^\s<>,;"']+/;
const fromEmail =
  msg.replyTo?.value?.[0]?.address ||
  msg.from?.value?.[0]?.address ||
  (String(rawGet('Reply-To') || from).match(addrRe) || [''])[0];

// --- Automated mail detection (newsletters, no-reply notifications) ---
const hdr = msg.headers || {};
const precedence = String(hdr['precedence'] || rawGet('Precedence') || '').replace(/^precedence:\s*/i, '').trim();
const isAutomated = Boolean(
  hdr['list-unsubscribe'] ||
  rawGet('List-Unsubscribe') ||
  /^(bulk|list|junk)$/i.test(precedence) ||
  /(^|[._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster)([._-]|@)/i.test(fromEmail)
);

return {
  json: {
    threadId: msg.threadId,
    messageId: msg.id,
    from,
    fromEmail,
    isAutomated,
    subject,
    body,
  }
};

