// Reads Claude's one-word answer. Anything unexpected becomes REVIEW (you get an alert) instead of being silently ignored.
const raw = String($input.item.json.content?.[0]?.text ?? '').trim().toUpperCase().replace(/[^A-Z_]/g, '');
const allowed = ['LEAD', 'CLIENT_QUESTION', 'INVOICE', 'URGENT', 'IGNORE'];
const email = $('Extract Email Content').item.json;

let category = allowed.includes(raw) ? raw : 'REVIEW';

// Automated mail (newsletters, no-reply notifications) never gets a drafted reply.
if (email.isAutomated && (category === 'LEAD' || category === 'CLIENT_QUESTION')) {
  category = 'IGNORE';
}

return {
  json: {
    ...email,
    category,
  }
};

