// Reads the invoice details Claude extracted. If the answer is unusable, or the amount is missing
// (e.g. the invoice is only a PDF attachment), the row is still logged but marked "needs_review".
const text = String($input.item.json.content?.[0]?.text ?? '');
const src = $('Parse Classification').item.json;

let parsed = null;
const match = text.match(/\{[\s\S]*\}/); // tolerate ```json fences or extra words around the JSON
try {
  parsed = match ? JSON.parse(match[0]) : null;
} catch {
  parsed = null;
}
if (!parsed || typeof parsed !== 'object') parsed = {};

const str = (v) => (v === null || v === undefined ? '' : String(v).trim());
const amount = str(parsed.amount);

return {
  json: {
    date_logged: new Date().toISOString().slice(0, 10),
    from: src.from,
    subject: src.subject,
    amount,
    currency: str(parsed.currency),
    due_date: str(parsed.due_date),
    status: amount ? 'pending' : 'needs_review',
  }
};

// Keeps only the conversations that really need a follow-up:
//  - the LAST real message of the thread was sent by you (nobody replied after it)
//  - that message is at least "follow_up_after_days" old (set in the Company Profile node)
//  - there is no pending draft in the thread yet (so you never get duplicates)
//  - the thread was not already followed up by this workflow (remembered between runs)
// Drafts, trash and spam are ignored when deciding who wrote last.
const days = Number($('Build Profile Text').first().json.follow_up_after_days) || 3;
const minAgeMs = days * 24 * 60 * 60 * 1000;
const now = Date.now();

const store = $getWorkflowStaticData('global');
const followedUp = store.followedUp || {};

const hasLabel = (m, id) => (m.labels || []).some((l) => (l.id || l) === id);
const emails = (s) => (String(s || '').match(/[^\s<>,;"']+@[^\s<>,;"']+/g) || []).join(', ');

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const thread = item.json;
  const threadId = thread.id || thread.threadId;
  if (!threadId || seen.has(threadId)) continue; // several sent messages can point at the same thread
  seen.add(threadId);
  if (followedUp[threadId]) continue;

  const messages = Array.isArray(thread.messages) ? thread.messages : [];
  const real = messages.filter((m) => !hasLabel(m, 'DRAFT') && !hasLabel(m, 'TRASH') && !hasLabel(m, 'SPAM'));
  if (real.length === 0) continue;

  const time = (m) => Number(m.internalDate) || 0;
  const last = real.reduce((a, b) => (time(b) >= time(a) ? b : a));

  if (!hasLabel(last, 'SENT')) continue;            // someone replied after you -> nothing to chase
  if (now - time(last) < minAgeMs) continue;         // not old enough yet
  if (messages.some((m) => hasLabel(m, 'DRAFT') && time(m) > time(last))) continue; // a draft is already waiting

  out.push({
    json: {
      threadId,
      subject: last.Subject || last.subject || '',
      to: emails(last.To || last.to),
      snippet: String(last.snippet || '').slice(0, 300),
    },
  });
}

return out;

